import sys

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    p = list(map(int, data[1:n+1]))
    b = list(map(int, data[n+1:2*n+1]))

    visited = [False] * (2 * n)

    changes = 0

    for i in range(n):
        pos = i
        for _ in range(2 * n):
            if not visited[pos]:
                visited[pos] = True
            else:
                changes += 1
                break

            pos = p[pos] - 1
            if b[pos] == 1:
                b[pos] = 0
            else:
                b[pos] = 1

    print(changes)

if __name__ == "__main__":
    main()
